import{_ as i,o as s,c as a,a0 as n}from"./chunks/framework.C3yZ6M33.js";const k=JSON.parse('{"title":"Include and snippet resolution","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/include-resolution.md","filePath":"explanation/include-resolution.md"}'),t={name:"explanation/include-resolution.md"};function l(d,e,p,r,h,o){return s(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="include-and-snippet-resolution" tabindex="-1">Include and snippet resolution <a class="header-anchor" href="#include-and-snippet-resolution" aria-label="Permalink to &quot;Include and snippet resolution&quot;">​</a></h1><p>Composition happens at two levels: <strong>file-level</strong> (the YAML loader expands <code>include:</code>/<code>snippet:</code> before the typed model ever sees the document) and <strong>distribution-level</strong> (an installed bundle&#39;s manifest <code>include:</code> deep-merges base bundles under the local payload). Both use the same merge rules.</p><p>The normative semantics — merge order, discovery, the normalization pass sequence — are specified in <a href="./../reference/campaign-schema.html">Campaign schema</a> and <a href="./../reference/distribution.html">Distribution</a>; this page is the map of <em>which mechanism solves which problem</em>.</p><h2 id="file-level-—-four-mechanisms-two-axes" tabindex="-1">File level — four mechanisms, two axes <a class="header-anchor" href="#file-level-—-four-mechanisms-two-axes" aria-label="Permalink to &quot;File level — four mechanisms, two axes&quot;">​</a></h2><p>Two granularities (merge a mapping vs inject a value) × two naming schemes (path vs name).</p><h3 id="include-—-merge-dict-level-path-based" tabindex="-1"><code>include:</code> — merge (dict-level, path-based) <a class="header-anchor" href="#include-—-merge-dict-level-path-based" aria-label="Permalink to &quot;`include:` — merge (dict-level, path-based)&quot;">​</a></h3><p>Works in any mapping. The loader (<code>peregrin-loader-yaml</code>) loads the file and deep-merges its content <em>under</em> the local keys; the <code>include</code> key is removed after resolution.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">params</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">snippets/prod-env.yaml</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deploy.sh&quot;</span></span></code></pre></div><p>Merge rules: local scalars win; dicts merge recursively per-key; arrays concatenate local-first; node <code>id</code> collisions dedupe keeping the local definition — an overlay that redefines a node can&#39;t double-fire it.</p><p><strong>Why merge, not replace:</strong> you want to include a base config and override specific fields. Merge gives you that for free.</p><h3 id="include-path-—-inject-value-level-path-based" tabindex="-1"><code>${include(path)}</code> — inject (value-level, path-based) <a class="header-anchor" href="#include-path-—-inject-value-level-path-based" aria-label="Permalink to &quot;`${include(path)}` — inject (value-level, path-based)&quot;">​</a></h3><p>Works in any string value. Whole-string match → the file&#39;s parsed content replaces it, preserving type (dict, list, scalar). Partial match → stringified interpolation.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">params</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">${include(snippets/prod-env.yaml)}</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deploy --region=${include(snippets/region.yaml)}&quot;</span></span></code></pre></div><p><strong>Why inject, not merge:</strong> sometimes you want a file&#39;s content at a specific position, not merged into the parent.</p><h3 id="snippet-name-—-merge-dict-level-name-based" tabindex="-1"><code>snippet: name</code> — merge (dict-level, name-based) <a class="header-anchor" href="#snippet-name-—-merge-dict-level-name-based" aria-label="Permalink to &quot;`snippet: name` — merge (dict-level, name-based)&quot;">​</a></h3><p>Snippets are named fragments in a top-level <code>snippets:</code> block — a <strong>load-time-only</strong> key that never reaches the typed <code>Campaign</code>. <code>snippet: &lt;name&gt;</code> in any mapping deep-merges the body under local keys; <code>snippet: &lt;parent&gt;</code> <em>inside</em> the snippets table is inheritance, resolved to a fixpoint (local wins, cycles error).</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">snippets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  devin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    driver</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">shell</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    params</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;devin run&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      timeout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1800</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">nodes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">review</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    snippet</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">devin</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pr.opened</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    params</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      timeout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3600</span></span></code></pre></div><p><strong>Why snippets, not just includes:</strong> includes are path-based — rename a file and every reference breaks. Snippets are name-based indirection inside a document.</p><h3 id="snippet-name-—-inject-value-level-name-based" tabindex="-1"><code>${snippet(name)}</code> — inject (value-level, name-based) <a class="header-anchor" href="#snippet-name-—-inject-value-level-name-based" aria-label="Permalink to &quot;`${snippet(name)}` — inject (value-level, name-based)&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">snippets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  pr-triggers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pr.opened</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pr.updated</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">nodes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">review</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">${snippet(pr-triggers)}</span></span></code></pre></div><h2 id="how-they-interact" tabindex="-1">How they interact <a class="header-anchor" href="#how-they-interact" aria-label="Permalink to &quot;How they interact&quot;">​</a></h2><p>Resolution is recursive, ordered, and cycle-checked:</p><ol><li><code>include:</code> resolution (deep-merge included files)</li><li><code>snippets:</code> block extraction + <code>snippet:</code>-in-table inheritance</li><li><code>snippet: name</code> resolution in mappings</li><li><code>${snippet(name)}</code> / <code>${include(path)}</code> string interpolation</li><li>Deep-merge pass (dicts per-key local-wins, arrays local-first)</li></ol><p>Then normalization continues — <code>with:</code> rejection, poll normalization, self-trigger <code>max_fires</code> defaults — per <a href="./../reference/campaign-schema.html">Campaign schema § Load-time normalization</a>.</p><p><strong>Path resolution:</strong> relative to the <em>including</em> file&#39;s directory, not the working directory. <code>include</code> cycles error by path.</p><h2 id="distribution-level-—-bundle-include" tabindex="-1">Distribution level — bundle <code>include:</code> <a class="header-anchor" href="#distribution-level-—-bundle-include" aria-label="Permalink to &quot;Distribution level — bundle `include:`&quot;">​</a></h2><p>A bundle manifest (<code>peregrin-bundle.yaml</code>) may declare its own <code>include: […]</code> — installed store names (<code>name</code> or <code>name@version</code>) or source refs installed on demand — whose payloads merge under the local one with the <em>same</em> rules (local wins, earlier entries outrank later). This is how a library bundle carries shared node fragments without vendoring them. See <a href="./../reference/distribution.html">Distribution § <code>include:</code> composition</a>.</p><h2 id="when-to-use-which" tabindex="-1">When to use which <a class="header-anchor" href="#when-to-use-which" aria-label="Permalink to &quot;When to use which&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Need</th><th>Use</th></tr></thead><tbody><tr><td>Include a node definition or config defaults</td><td><code>include: snippets/lint.yaml</code></td></tr><tr><td>Inject a dict/list/scalar as a specific value</td><td><code>${include(file)}</code> / <code>${snippet(name)}</code></td></tr><tr><td>Reusable node template by name</td><td><code>snippet: devin</code></td></tr><tr><td>Reusable value fragment by name</td><td><code>on: ${snippet(pr-triggers)}</code></td></tr><tr><td>Share fragments across workflows in one repo</td><td><code>include:</code> a <code>snippets:</code> file, then <code>snippet: name</code></td></tr><tr><td>Share fragments across machines/git refs</td><td>a bundle — <code>peregrin install</code>, manifest <code>include:</code></td></tr></tbody></table>',29)])])}const u=i(t,[["render",l]]);export{k as __pageData,u as default};
